// components/ScreenWrapper.js
import React from 'react';
import { Platform } from 'react-native';

const VH = (typeof CSS !== 'undefined' && CSS.supports && CSS.supports('height', '100dvh')) ? '100dvh' : '100vh';

const ScreenWrapper = ({ children }) => {
  // Only apply web-specific styles on web platform
  if (Platform.OS === 'web') {
    return (
      <div 
        style={{
          minHeight: VH,
          maxHeight: VH,
          overflowY: 'auto',
          WebkitOverflowScrolling: 'touch',
          backgroundColor: '#fff',
        }}
      >
        {children}
      </div>
    );
  }

  // Return children as-is for mobile platforms
  return children;
};

export default ScreenWrapper;